const HTML = "<div style=\"font-family: var(--font-libre-franklin), 'Libre Franklin', system-ui, sans-serif; color: #16325B; background: #FBF6EC;\">\n\n  <header class=\"site-header\" id=\"site-header\">\n    <div class=\"menu-shell\" style=\"display: flex; align-items: center; justify-content: space-between; gap: 20px; flex-wrap: nowrap;\">\n      <img class=\"header-logo\" src=\"/assets/home/d01d776f-f9a5-40a7-a7f1-7d5f1cc62e61.png\" alt=\"Scramblers Diner\">\n      <nav style=\"display: flex; flex-wrap: nowrap; gap: 26px; font-family: 'Barlow Condensed', sans-serif; font-size: 19px; letter-spacing: 0.08em; text-transform: uppercase;\">\n        <a href=\"/\" class=\"is-active\" style=\"color: #16325B;\">Home</a>\n        <a href=\"/menu\" style=\"color: #16325B;\">Menu</a>\n        <a href=\"/catering\" style=\"color: #16325B;\">Catering</a>\n        <a href=\"/gallery\" style=\"color: #16325B;\">Gallery</a>\n        <a href=\"/about\" style=\"color: #16325B;\">About</a>\n        <a href=\"/contact\" style=\"color: #16325B;\">Contact</a>\n      </nav>\n      <div class=\"header-actions\" style=\"display: flex; align-items: center; gap: 12px; flex-wrap: nowrap;\">\n        <a href=\"tel:4178864224\" class=\"header-phone\" style=\"display: inline-flex; align-items: center; gap: 8px; font-family: 'Archivo Black', sans-serif; font-size: 18px; color: #16325B; letter-spacing: -0.01em;\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M6.62 10.79a15.05 15.05 0 006.59 6.59l2.2-2.2a1 1 0 011.01-.24c1.12.37 2.33.57 3.58.57a1 1 0 011 1V20a1 1 0 01-1 1C10.85 21 3 13.15 3 3a1 1 0 011-1h3.5a1 1 0 011 1c0 1.25.2 2.46.57 3.58a1 1 0 01-.25 1.02l-2.2 2.19z\"/></svg><span>417-886-4224</span></a>\n        <a href=\"/menu\" class=\"header-menu-btn is-btn\" style=\"background: #16325B; color: #FFF; font-family: 'Barlow Condensed', sans-serif; font-size: 17px; letter-spacing: 0.1em; text-transform: uppercase; padding: 12px 20px; border-radius: 999px;\">View our Menu</a>\n      </div>\n    </div>\n  </header>\n\n  <section class=\"home-hero\" data-screen-label=\"Hero\" style=\"background: #FBF6EC; color: #16325B;\">\n    <div style=\"max-width: 1400px; margin: 0 auto; padding: 72px 40px 80px; display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 400px), 1fr)); gap: 40px 40px; align-items: center;\">\n      <div style=\"min-width: 0;\">\n        <p class=\"home-hero__kicker\">Springfield, Missouri &nbsp;·&nbsp; Since 1997</p>\n        <h1 class=\"home-hero__title\" style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-size: clamp(40px, 4.8vw, 72px); line-height: 1.02; letter-spacing: -0.02em; text-wrap: balance;\"><span class=\"home-hero__line\">Big Breakfasts.</span><span class=\"home-hero__line\">Great Food.</span><span class=\"home-hero__line\" style=\"color: #D81E29;\">Come Hungry.</span></h1>\n        <p class=\"home-hero__caption\">From our famous four-egg omelets to classic breakfast favorites and satisfying lunch plates, Scrambler's serves generous portions with a welcoming, hometown feel.</p>\n        <div style=\"display: flex; flex-wrap: wrap; gap: 14px; margin-top: 34px;\">\n          <a href=\"/menu\" class=\"is-btn is-btn-filled-navy\" style=\"background: #16325B; color: #FFF; font-family: 'Barlow Condensed', sans-serif; font-size: 20px; letter-spacing: 0.1em; text-transform: uppercase; padding: 16px 30px; border-radius: 999px; border: 2px solid #16325B;\">See the Menu</a>\n          <a href=\"#visit\" class=\"is-btn is-btn-outline-dark\" style=\"border: 2px solid #16325B; color: #16325B; font-family: 'Barlow Condensed', sans-serif; font-size: 20px; letter-spacing: 0.1em; text-transform: uppercase; padding: 14px 30px; border-radius: 999px; background: transparent;\">Plan Your Visit</a>\n        </div>\n      </div>\n      <figure class=\"home-hero__figure\" style=\"margin: 0; position: relative; min-width: 0; display: flex; justify-content: center; padding: 20px;\">\n        <svg width=\"0\" height=\"0\" style=\"position: absolute;\" aria-hidden=\"true\"><defs><clipPath id=\"heroBlob\" clipPathUnits=\"objectBoundingBox\"><path d=\"M0.56,0.03 C0.7,0.0 0.84,0.06 0.92,0.18 C1.0,0.3 0.99,0.44 0.96,0.57 C0.93,0.72 0.88,0.86 0.74,0.94 C0.6,1.01 0.43,0.99 0.29,0.93 C0.15,0.87 0.04,0.75 0.02,0.6 C0.0,0.45 0.05,0.3 0.15,0.19 C0.26,0.08 0.41,0.05 0.56,0.03 Z\"></path></clipPath></defs></svg>\n        <div style=\"position: relative; width: 100%; max-width: 700px; aspect-ratio: 1 / 1;\">\n          <svg viewBox=\"0 0 1 1\" preserveAspectRatio=\"none\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: translate(5%, -3%) rotate(14deg) scale(1.02);\" aria-hidden=\"true\"><path d=\"M0.56,0.03 C0.7,0.0 0.84,0.06 0.92,0.18 C1.0,0.3 0.99,0.44 0.96,0.57 C0.93,0.72 0.88,0.86 0.74,0.94 C0.6,1.01 0.43,0.99 0.29,0.93 C0.15,0.87 0.04,0.75 0.02,0.6 C0.0,0.45 0.05,0.3 0.15,0.19 C0.26,0.08 0.41,0.05 0.56,0.03 Z\" fill=\"#FFD21E\"></path></svg>\n          <svg viewBox=\"0 0 1 1\" preserveAspectRatio=\"none\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; transform: translate(-3.5%, 3.5%) rotate(-7deg);\" aria-hidden=\"true\"><path d=\"M0.56,0.03 C0.7,0.0 0.84,0.06 0.92,0.18 C1.0,0.3 0.99,0.44 0.96,0.57 C0.93,0.72 0.88,0.86 0.74,0.94 C0.6,1.01 0.43,0.99 0.29,0.93 C0.15,0.87 0.04,0.75 0.02,0.6 C0.0,0.45 0.05,0.3 0.15,0.19 C0.26,0.08 0.41,0.05 0.56,0.03 Z\" fill=\"none\" stroke=\"#16325B\" stroke-width=\"3\" vector-effect=\"non-scaling-stroke\"></path></svg>\n          <div style=\"position: absolute; inset: 0; clip-path: url(#heroBlob); filter: drop-shadow(0 20px 30px rgba(22,50,91,0.2));\">\n            <img src=\"/images/hero-storefront-front.webp\" alt=\"Scrambler's Diner storefront on Republic Road\" style=\"width: 100%; height: 100%; object-fit: cover; object-position: center 22%; display: block;\">\n          </div>\n          <a href=\"https://www.google.com/maps/search/?api=1&query=1131+E.+Republic+Rd+Springfield+MO+65807\" target=\"_blank\" rel=\"noopener\" style=\"position: absolute; left: 2%; bottom: 14%; background: #D81E29; color: #FFFFFF; font-family: 'Barlow Condensed', sans-serif; font-size: 16px; letter-spacing: 0.14em; text-transform: uppercase; padding: 9px 18px; border-radius: 999px; box-shadow: 0 8px 18px rgba(22,50,91,0.2);\">1131 E. Republic Rd, Springfield, MO</a>\n        </div>\n      </figure>\n    </div>\n  </section>\n\n  <section id=\"visit\" style=\"background: #16325B; color: #FBF6EC; padding: 74px 40px 80px;\">\n    <div style=\"max-width: 1280px; margin: 0 auto;\">\n      <div style=\"text-align: center; max-width: 1100px; margin: 0 auto 46px;\">\n        <p style=\"margin: 0 0 12px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #FFD21E;\">What we do</p>\n        <h2 style=\"margin: 0 0 16px; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.04; letter-spacing: -0.02em; white-space: nowrap;\">Three ways to eat with us</h2>\n        <p style=\"margin: 0; font-size: 18px; line-height: 1.65; color: rgba(251,246,236,0.85); white-space: nowrap;\">Whether it's a booth for two or breakfast for a hundred, we've got a plate for it.</p>\n      </div>\n      <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 22px;\">\n        <article style=\"background: #FBF6EC; color: #16325B; border-radius: 22px; padding: 34px 32px 36px; display: flex; flex-direction: column; gap: 16px; min-width: 0;\">\n          <span style=\"font-family: 'Barlow Condensed', sans-serif; font-size: 15px; letter-spacing: 0.2em; text-transform: uppercase; color: #D81E29;\">Every day, 6am-2pm</span>\n          <h3 style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-size: 30px; line-height: 1.05; letter-spacing: -0.02em;\">Dine-In &amp; Carryout</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.6; color: rgba(22,50,91,0.8);\">Four-egg omelets, skillets, pancakes and waffles in the morning; burgers, sandwiches and salads at lunch. Eat in or call ahead.</p>\n          <a class=\"is-btn is-btn-filled-navy\" href=\"/menu\" style=\"display:inline-block;background:#16325B;border:2px solid #16325B;color:#FFFFFF;font-family:'Barlow Condensed',sans-serif;font-size:16px;letter-spacing:0.08em;text-transform:uppercase;padding:10px 18px;border-radius:999px;margin-top:auto;align-self:flex-start;\">See hours &amp; menu</a>\n        </article>\n        <article style=\"background: #FBF6EC; color: #16325B; border-radius: 22px; padding: 34px 32px 36px; display: flex; flex-direction: column; gap: 16px; min-width: 0;\">\n          <span style=\"font-family: 'Barlow Condensed', sans-serif; font-size: 15px; letter-spacing: 0.2em; text-transform: uppercase; color: #D81E29;\">Any size group</span>\n          <h3 style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-size: 30px; line-height: 1.05; letter-spacing: -0.02em;\">Parties &amp; Events</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.6; color: rgba(22,50,91,0.8);\">Private parties, school and team fundraisers, club gatherings and business meetings  -  hosted here or handled for you.</p>\n          <a class=\"is-btn is-btn-filled-navy\" href=\"/catering\" style=\"display:inline-block;background:#16325B;border:2px solid #16325B;color:#FFFFFF;font-family:'Barlow Condensed',sans-serif;font-size:16px;letter-spacing:0.08em;text-transform:uppercase;padding:10px 18px;border-radius:999px;margin-top:auto;align-self:flex-start;\">Plan a party</a>\n        </article>\n        <article style=\"background: #FBF6EC; color: #16325B; border-radius: 22px; padding: 34px 32px 36px; display: flex; flex-direction: column; gap: 16px; min-width: 0;\">\n          <span style=\"font-family: 'Barlow Condensed', sans-serif; font-size: 15px; letter-spacing: 0.2em; text-transform: uppercase; color: #D81E29;\">Free delivery &amp; setup</span>\n          <h3 style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-size: 30px; line-height: 1.05; letter-spacing: -0.02em;\">Catering</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.6; color: rgba(22,50,91,0.8);\">Lots of breakfast offerings including eggs, pancakes, waffles and French toast, plus several lunch items. Competitive pricing, free delivery and setup.</p>\n          <a class=\"is-btn is-btn-filled-navy\" href=\"/catering\" style=\"display:inline-block;background:#16325B;border:2px solid #16325B;color:#FFFFFF;font-family:'Barlow Condensed',sans-serif;font-size:16px;letter-spacing:0.08em;text-transform:uppercase;padding:10px 18px;border-radius:999px;margin-top:auto;align-self:flex-start;\">Learn more</a>\n        </article>\n      </div>\n      <div style=\"display: flex; flex-wrap: wrap; gap: 14px; justify-content: center; align-items: center; margin-top: 44px;\">\n        <a class=\"is-btn is-btn-outline-light\" href=\"/menu\" style=\"display:inline-block;background:transparent;border:2px solid #FBF6EC;color:#FBF6EC;font-family:'Barlow Condensed',sans-serif;font-size:20px;letter-spacing:0.1em;text-transform:uppercase;padding:14px 30px;border-radius:999px;\">View our Menu</a>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"home-griddle\" style=\"max-width: 1280px; margin: 0 auto; padding: 84px 0 20px;\">\n    <div>\n      <div>\n        <p style=\"margin: 0 0 10px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #D81E29;\">Off the Griddle</p>\n        <h2 style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.04; letter-spacing: -0.02em;\">Plates our regulars<br>order by name</h2>\n      </div>\n    </div>\n\n        \n    <div class=\"sd-carousel sd-carousel--flush\" id=\"griddle-carousel\" data-i=\"0\">\n      <div class=\"sd-carousel__viewport\">\n        <div class=\"sd-carousel__track\" data-i=\"0\" style=\"display:flex;\">\n          <div class=\"sd-carousel__slide\"><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/45e4a725-e4ff-4698-929d-96755bc1fcb0.png\" alt=\"Bacon, scrambled eggs and hashbrowns\" style=\"width:100%;height:180px;object-fit:contain;display:block;mix-blend-mode:multiply;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Bacon, Eggs &amp; Hashbrowns</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">The classic. Thick-cut bacon, eggs your way, and hashbrowns crisped on the flat top.</p>\n        </article><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/f49b1ee6-177a-47f5-8673-da61a4e10b43.png\" alt=\"Bacon, eggs and breakfast potatoes\" style=\"width:100%;height:180px;object-fit:contain;display:block;mix-blend-mode:multiply;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Bacon, Eggs &amp; Potatoes</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">Seasoned breakfast potatoes alongside eggs and bacon. Add raisin bread toast made from scratch.</p>\n        </article><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/78aa8c5d-66a3-4331-98ac-0f2abbaac862.png\" alt=\"French toast dusted with powdered sugar\" style=\"width:100%;height:180px;object-fit:contain;display:block;mix-blend-mode:multiply;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Raisin Bread French Toast</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">Griddled from our from-scratch family raisin bread recipe, with warm syrup and butter.</p>\n        </article></div>\n          <div class=\"sd-carousel__slide\"><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/71255646-1315-4cca-ae24-88bb7a4de44e-white.png\" alt=\"Hashbrown casserole with gravy and eggs\" style=\"width:100%;height:180px;object-fit:contain;display:block;background:#fff;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Hashbrown Casserole</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">Hashbrowns, country gravy, and eggs your way - a skillet that eats like a meal.</p>\n        </article><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/1fb0a129-8178-4bd6-bc29-e515bc225f19-white.png\" alt=\"Blueberry pancakes with butter and maple syrup\" style=\"width:100%;height:180px;object-fit:contain;display:block;background:#fff;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Blueberry Pancakes</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">Tall griddle cakes studded with blueberries, served with butter and warm syrup.</p>\n        </article><article class=\"sd-dish-card\">\n          <div style=\"display:flex;align-items:center;justify-content:center;\">\n            <img src=\"/assets/home/022af95e-1aea-4d3d-aeed-fc2d26935f23.png\" alt=\"Skillet breakfast special\" style=\"width:100%;height:180px;object-fit:contain;display:block;mix-blend-mode:multiply;\">\n          </div>\n          <h3 style=\"margin:0;font-family:'Archivo Black',sans-serif;font-size:20px;color:#16325B;\">Skillet Special</h3>\n          <p style=\"margin:0;font-family: var(--font-libre-franklin), 'Libre Franklin',sans-serif;font-size:15px;line-height:1.55;color:rgba(22,50,91,0.8);\">A generous cast-iron plate - eggs, hashbrowns, and the works.</p>\n        </article></div>\n        </div>\n      </div>\n      <div class=\"sd-carousel__dots\"><button type=\"button\" class=\"sd-carousel__dot is-active\" aria-label=\"Go to slide 1\" data-sd-go=\"0\"></button><button type=\"button\" class=\"sd-carousel__dot\" aria-label=\"Go to slide 2\" data-sd-go=\"1\"></button></div>\n    </div>\n    <div class=\"home-griddle__cta\" style=\"display:flex;justify-content:center;margin-top:28px;\">\n      <a href=\"/menu\" class=\"is-btn is-btn-outline-dark\" style=\"display:inline-flex;align-items:center;gap:8px;font-family:'Barlow Condensed',sans-serif;font-size:17px;letter-spacing:0.08em;text-transform:uppercase;color:#16325B;border:2px solid #16325B;border-radius:999px;padding:12px 24px;background:#FFF;\">View the full menu →</a>\n    </div>\n  </section>\n\n  <section style=\"background: #FFFFFF; padding: 84px 40px;\">\n    <div style=\"max-width: 1280px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 30px;\">\n      <div style=\"min-width: 0;\">\n        <p style=\"margin: 0 0 10px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #D81E29;\">Why folks keep coming back</p>\n        <h2 style=\"margin: 0 0 18px; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.06; letter-spacing: -0.02em;\">Great food, great service, great prices.</h2>\n        <p style=\"margin: 0; font-size: 18px; line-height: 1.65; color: rgba(22,50,91,0.85); max-width: 40ch;\">We've been around long enough to see generations, new and old, make us their favorite breakfast stop.</p>\n        <a id=\"why-menu-cta\" href=\"/menu\" class=\"is-btn is-btn-filled-navy\" style=\"display: inline-block; margin-top: 28px; background: #16325B; color: #FFF; font-family: 'Barlow Condensed', sans-serif; font-size: 18px; letter-spacing: 0.1em; text-transform: uppercase; padding: 14px 26px; border-radius: 999px; border: 2px solid #16325B;\">View our Menu</a>\n      </div>\n      <div style=\"display: grid; gap: 18px; min-width: 0;\">\n        <div style=\"background: #FBF6EC; border-left: 6px solid #FFD21E; border-radius: 4px 18px 18px 4px; padding: 22px 24px;\">\n          <h3 style=\"margin: 0 0 8px; font-family: 'Archivo Black', sans-serif; font-size: 19px;\">Four-egg omelets, generous portions</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.55; color: rgba(22,50,91,0.8);\">Our signature omelets are built on four eggs, and nobody leaves hungry.</p>\n        </div>\n        <div style=\"background: #FBF6EC; border-left: 6px solid #D81E29; border-radius: 4px 18px 18px 4px; padding: 22px 24px;\">\n          <h3 style=\"margin: 0 0 8px; font-family: 'Archivo Black', sans-serif; font-size: 19px;\">From-scratch family recipes</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.55; color: rgba(22,50,91,0.8);\">The raisin bread and buttermilk biscuits are the best from-scratch family recipes around.</p>\n        </div>\n        <div style=\"background: #FBF6EC; border-left: 6px solid #16325B; border-radius: 4px 18px 18px 4px; padding: 22px 24px;\">\n          <h3 style=\"margin: 0 0 8px; font-family: 'Archivo Black', sans-serif; font-size: 19px;\">Treated like family, every visit</h3>\n          <p style=\"margin: 0; font-size: 18px; line-height: 1.55; color: rgba(22,50,91,0.8);\">A relaxed, comfortable room, quick service, and prices that work for the whole table.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"testimonials\" style=\"background: #FFF7DC; padding: 84px 40px;\">\n    <div style=\"max-width: 1280px; margin: 0 auto;\">\n      <div style=\"text-align: center; max-width: 720px; margin: 0 auto 40px;\">\n        <p style=\"margin: 0 0 12px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #D81E29;\">Testimonials</p>\n        <h2 style=\"margin: 0 0 16px; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.06;\">Guests who keep coming back</h2>\n        <p style=\"margin: 0; font-size: 17px; line-height: 1.65; color: rgba(22,50,91,0.8);\">Real reviews from breakfast regulars and first-timers in Springfield.</p>\n      </div>\n      <div class=\"sd-carousel sd-carousel--flush\" id=\"testimonials-carousel\">\n        <div class=\"sd-carousel__viewport\">\n          <div class=\"sd-carousel__track\" data-i=\"0\" style=\"display:flex;\"><div class=\"sd-carousel__slide\"><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">Y</div>\n            <div>\n              <p class=\"sd-review-card__name\">Yolanda W.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">If you're looking for the old diner experience, this is the place. Staff was very friendly, they knew their regulars by name. The pancakes were top notch!!</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">A</div>\n            <div>\n              <p class=\"sd-review-card__name\">Aleesha N.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">The food was delicious, and our server, Joey, is a great guy. Everyone here is very nice, and the place is clean and welcoming.</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">S</div>\n            <div>\n              <p class=\"sd-review-card__name\">Sierra H.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">This is the best place I've been for breakfast. We had the absolute best waitress; she walked us through the menu. 10/10 recommend!</p>\n        </article></div><div class=\"sd-carousel__slide\"><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">M</div>\n            <div>\n              <p class=\"sd-review-card__name\">Marcie B.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">Wow, what a hidden gem. The service here was Amazing! Thank you Lori!! The food tastes amazing and the prices are so reasonable.</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">K</div>\n            <div>\n              <p class=\"sd-review-card__name\">Kenyen</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">Hands down the best breakfast in Springfield. My server was great. The Cox family gets 100 stars from me. Thank you!!</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">A</div>\n            <div>\n              <p class=\"sd-review-card__name\">Abby</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">The most delicious homemade cinnamon raisin bread French toast, perfectly cooked bacon, and bottomless coffee! Lori was superb.</p>\n        </article></div><div class=\"sd-carousel__slide\"><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">S</div>\n            <div>\n              <p class=\"sd-review-card__name\">Stefanie F.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">New to Springfield and looking for a Good Ol' Breakfast place - I found a gem. Eggs Benedict was amazing.</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">C</div>\n            <div>\n              <p class=\"sd-review-card__name\">Collene E.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">Truly great American diner. Delicious food, made from scratch, and plentiful. Kind, friendly waitstaff, quick service.</p>\n        </article><article class=\"sd-review-card\">\n          <div class=\"sd-review-card__top\">\n            <div class=\"sd-review-card__avatar\">W</div>\n            <div>\n              <p class=\"sd-review-card__name\">Walter H.</p>\n            </div>\n            <svg class=\"sd-google\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path fill=\"#FFC107\" d=\"M43.6 20.1H42V20H24v8h11.3C33.7 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.3-.1-2.7-.4-3.9z\"/><path fill=\"#FF3D00\" d=\"M6.3 14.7l6.6 4.8C14.7 15.1 19 12 24 12c3.1 0 5.8 1.2 8 3l5.7-5.7C34.2 6.1 29.4 4 24 4 16.3 4 9.7 8.3 6.3 14.7z\"/><path fill=\"#4CAF50\" d=\"M24 44c5.2 0 10-2 13.6-5.2l-6.3-5.3C29.2 35.1 26.7 36 24 36c-5.3 0-9.7-3.3-11.3-8l-6.5 5C9.5 39.6 16.2 44 24 44z\"/><path fill=\"#1976D2\" d=\"M43.6 20.1H42V20H24v8h11.3c-1.1 3.1-3.5 5.5-6.6 6.5l.1.1 6.3 5.3C36.9 41.1 44 36 44 24c0-1.3-.1-2.7-.4-3.9z\"/></svg>\n          </div>\n          <div class=\"sd-review-card__stars\" aria-hidden=\"true\">★★★★★</div>\n          <p class=\"sd-review-card__text\">This is our go-to place for breakfast. There is a huge breakfast menu, and everything I've tried has been great.</p>\n        </article></div></div>\n        </div>\n        <div class=\"sd-carousel__dots\"><button type=\"button\" class=\"sd-carousel__dot is-active\" aria-label=\"Go to slide 1\" data-sd-go=\"0\"></button><button type=\"button\" class=\"sd-carousel__dot\" aria-label=\"Go to slide 2\" data-sd-go=\"1\"></button><button type=\"button\" class=\"sd-carousel__dot\" aria-label=\"Go to slide 3\" data-sd-go=\"2\"></button></div>\n      </div>\n    <div style=\"text-align:center;margin-top:36px;\"><a class=\"is-btn is-btn-outline-dark\" href=\"/testimonials\" style=\"display:inline-block;background:transparent;border:2px solid #16325B;color:#16325B;font-family:'Barlow Condensed',sans-serif;font-size:18px;letter-spacing:0.1em;text-transform:uppercase;padding:14px 28px;border-radius:999px;text-decoration:none;\">View Testimonials</a></div>\n    </div>\n  </section>\n\n  <section id=\"catering\" class=\"home-catering\" style=\"background: #16325B; color: #FFFFFF;\">\n    <div class=\"home-catering__grid\" style=\"max-width: 1280px; margin: 0 auto; padding: 76px 40px;\">\n      <div class=\"home-catering__copy\" style=\"min-width: 0;\">\n        <p style=\"margin: 0 0 10px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #FFD21E;\">Catering</p>\n        <h2 style=\"margin: 0 0 18px; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.04; letter-spacing: -0.02em;\">We'll bring breakfast to your meeting.</h2>\n        <p style=\"margin: 0 0 24px; font-size: 18px; line-height: 1.65; max-width: 48ch;\">Lots of breakfast offerings, including eggs, pancakes, waffles, French toast, and many others. Very competitive pricing, free delivery and setup. Several lunch items also available.</p>\n        <div class=\"home-catering__tags\" style=\"display: flex; flex-wrap: wrap; gap: 12px; margin-bottom: 0; font-family: 'Barlow Condensed', sans-serif; font-size: 18px; letter-spacing: 0.1em; text-transform: uppercase;\">\n          <span style=\"border: 1.5px solid rgba(255,255,255,0.55); border-radius: 999px; padding: 8px 18px;\">Business meetings</span>\n          <span style=\"border: 1.5px solid rgba(255,255,255,0.55); border-radius: 999px; padding: 8px 18px;\">Fundraisers</span>\n          <span style=\"border: 1.5px solid rgba(255,255,255,0.55); border-radius: 999px; padding: 8px 18px;\">Private parties</span>\n          <span style=\"border: 1.5px solid rgba(255,255,255,0.55); border-radius: 999px; padding: 8px 18px;\">Group events</span>\n        </div>\n      </div>\n      <div class=\"home-catering__media\" style=\"min-width: 0;\">\n        <img class=\"home-catering__img home-catering__img--storefront\" src=\"/assets/home/65eeb342-906d-4673-bdca-cda25aa757c0.png\" alt=\"Scramblers Diner storefront sign\" style=\"width: 100%; height: 100%; min-height: 200px; object-fit: cover; object-position: center 12%; border-radius: 18px; display: block;\">\n        <img class=\"home-catering__img\" src=\"/assets/home/1728ba1f-64b8-49a6-ae86-036fabcfd011.png\" alt=\"Scramblers Diner dining room with blue booths\" style=\"width: 100%; height: 100%; min-height: 200px; object-fit: cover; object-position: center; border-radius: 18px; display: block;\">\n      </div>\n      <div class=\"home-catering__actions\" style=\"display: flex; flex-wrap: wrap; gap: 14px;\">\n        <a href=\"/contact\" class=\"is-btn is-btn-filled-yellow\" style=\"background: #FFD21E; color: #16325B; font-family: 'Barlow Condensed', sans-serif; font-size: 20px; letter-spacing: 0.1em; text-transform: uppercase; padding: 16px 30px; border-radius: 999px; border: 2px solid #FFD21E;\">Request a Catering Quote</a>\n        <a href=\"tel:4178864224\" class=\"is-btn is-btn-outline-light\" style=\"border: 2px solid rgba(255,255,255,0.7); color: #FFFFFF; font-family: 'Barlow Condensed', sans-serif; font-size: 20px; letter-spacing: 0.1em; text-transform: uppercase; padding: 14px 30px; border-radius: 999px; background: transparent;\">Call 417-886-4224</a>\n      </div>\n    </div>\n  </section>\n\n  <section style=\"max-width: 1280px; margin: 0 auto; padding: 84px 40px; display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 48px; align-items: center;\">\n    <div style=\"min-width: 0; position: relative;\">\n      <img src=\"/assets/home/541e8605-0b2d-4ba6-b39d-eabf0e045dd7.jpg\" alt=\"The Scrambler's Diner family\" style=\"width: 100%; height: 490px; object-fit: cover; object-position: center top; border-radius: 20px; display: block;\">\n      <div style=\"position: absolute; right: -12px; bottom: -22px; background: #FFD21E; color: #16325B; border-radius: 16px; padding: 18px 22px; max-width: 230px; box-shadow: 0 14px 30px rgba(22,50,91,0.18);\">\n        <p style=\"margin: 0; font-family: var(--font-libre-franklin), 'Libre Franklin', sans-serif; font-size: 18px; line-height: 1.3;\">Bill &amp; Julie Cox</p>\n        <p style=\"margin: 6px 0 0; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.1em; text-transform: uppercase; font-size: 14px;\">Owners since 1997</p>\n      </div>\n    </div>\n    <div style=\"min-width: 0;\">\n      <p style=\"margin: 0 0 10px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #D81E29;\">Our story</p>\n      <h2 style=\"margin: 0 0 20px; font-family: 'Archivo Black', sans-serif; font-size: 36px; line-height: 1.06; letter-spacing: -0.02em;\">A family business, built on breakfast</h2>\n      <p style=\"margin: 0 0 16px; font-size: 18px; line-height: 1.65; color: rgba(22,50,91,0.85);\">Bill and Julie Cox have a combined total of over 53 years in the restaurant business and have always been involved in the local communities, especially the school systems through fundraisers.</p>\n      <p style=\"margin: 0 0 26px; font-size: 18px; line-height: 1.65; color: rgba(22,50,91,0.85);\">They love working with the young kids starting their first job. It has been an extreme joy watching these kids grow up and go out to be successful pillars in the communities that they grew up in.</p>\n      <div style=\"display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 28px; font-family: 'Barlow Condensed', sans-serif; font-size: 18px; letter-spacing: 0.14em; text-transform: uppercase;\">\n        <span style=\"background: #16325B; color: #FBF6EC; border-radius: 999px; padding: 8px 18px;\">God</span>\n        <span style=\"background: #16325B; color: #FBF6EC; border-radius: 999px; padding: 8px 18px;\">Family</span>\n        <span style=\"background: #16325B; color: #FBF6EC; border-radius: 999px; padding: 8px 18px;\">School</span>\n        <span style=\"background: #16325B; color: #FBF6EC; border-radius: 999px; padding: 8px 18px;\">Work</span>\n      </div>\n      <a class=\"is-btn is-btn-outline-dark\" href=\"/about\" style=\"display:inline-block;background:transparent;border:2px solid #16325B;color:#16325B;font-family:'Barlow Condensed',sans-serif;font-size:20px;letter-spacing:0.1em;text-transform:uppercase;padding:14px 30px;border-radius:999px;\">Read more about us</a>\n    </div>\n  </section>\n\n  <section class=\"cta-banner\" style=\"position: relative; isolation: isolate; padding: 84px 40px; overflow: hidden; background: #111111;\">\n    <div style=\"position: absolute; inset: 0; z-index: 0; background-image: url('/assets/home/de59b319-3979-4780-a64d-7a088c4697d8.webp'); background-size: cover; background-position: center; filter: contrast(1.08) saturate(1.1) brightness(1.02);\"></div>\n    <div style=\"position: absolute; inset: 0; z-index: 1; background: linear-gradient(to right, rgba(0, 0, 0, 0.88) 38%, rgba(0, 0, 0, 0.62) 55%, rgba(0, 0, 0, 0.28) 72%, rgba(0, 0, 0, 0.08) 100%);\"></div>\n    <div style=\"position: relative; z-index: 2; max-width: 1280px; margin: 0 auto; text-align: left;\">\n      <p class=\"subhead\" style=\"margin: 0 0 4px; font-family: 'Barlow Condensed', sans-serif; letter-spacing: 0.22em; text-transform: uppercase; font-size: 18px; color: #FFD21E;\">Pull up a chair</p>\n      <h2 class=\"cta-heading\" style=\"margin: 0; font-family: 'Archivo Black', sans-serif; font-style: normal; letter-spacing: -0.02em; color: #FFFFFF; max-width: none; white-space: nowrap; text-shadow: 0 2px 16px rgba(22,50,91,0.35); text-transform: none;\">Breakfast worth driving for.</h2>\n      <p class=\"cta-desc\" style=\"font-family: var(--font-libre-franklin), 'Libre Franklin', sans-serif; color: #FFFFFF; text-shadow: 0 1px 10px rgba(22,50,91,0.25);\">Four-egg omelets, skillets, and homemade toast - open daily until 2pm.</p>\n      <div style=\"display: flex; flex-wrap: wrap; gap: 14px; justify-content: flex-start; margin-top: 38px;\">\n        <a class=\"is-btn is-btn-cta-menu\" href=\"/menu\" style=\"display:inline-block;background:#FFFFFF;border:2px solid #FFFFFF;color:#16325B;font-family:'Barlow Condensed',sans-serif;font-size:20px;letter-spacing:0.1em;text-transform:uppercase;padding:14px 30px;border-radius:999px;\">See the Menu</a>\n        <a class=\"is-btn is-btn-outline-light\" href=\"#visit\" style=\"display:inline-block;background:transparent;border:2px solid #FFFFFF;color:#FFFFFF;font-family:'Barlow Condensed',sans-serif;font-size:20px;letter-spacing:0.1em;text-transform:uppercase;padding:14px 30px;border-radius:999px;\">Plan Your Visit</a>\n      </div>\n    </div>\n  </section>\n\n  <footer class=\"home-footer footer--franklin footer--fw\" style=\"background: #16325B; color: #FBF6EC; padding: 64px 40px 0; font-family: var(--font-libre-franklin), 'Libre Franklin', system-ui, sans-serif;\">\n    <div class=\"footer-fw\">\n      <div class=\"footer-fw__brand\">\n        <div class=\"footer-fw__identity\">\n          <img src=\"/assets/home/976e0da4-c1da-43ba-a05b-26ee50f111bb.png\" alt=\"Scrambler's Diner\">\n          <div>\n            <p class=\"footer-fw__name\">Scrambler's Diner</p>\n            <p class=\"footer-fw__tag\">Breakfast &amp; lunch · Est. 1997</p>\n          </div>\n        </div>\n        \n        <div class=\"footer-fw__follow\">\n          <span>Follow us on:</span>\n          <a href=\"https://www.facebook.com/scramblersdiner417\" aria-label=\"Facebook\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M22 12a10 10 0 10-11.5 9.9v-7h-2.2V12h2.2V9.8c0-2.2 1.3-3.4 3.3-3.4.96 0 1.96.17 1.96.17v2.16h-1.1c-1.09 0-1.43.68-1.43 1.37V12h2.43l-.39 2.9h-2.04v7A10 10 0 0022 12z\"/></svg></a>\n          <a href=\"https://www.doordash.com/store/scramblers-springfield-403703/23639549/\" aria-label=\"DoorDash\"><svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z\"/></svg></a>\n        </div>\n      </div>\n      <div class=\"footer-fw__hours\">\n        <p class=\"footer-fw__heading\">Hours</p>\n        <p>Mon–Sat 6:00 a.m. – 2:00 p.m.</p>\n        <p>Sun 7:00 a.m. – 2:00 p.m.</p>\n      </div>\n      <div class=\"footer-fw__links\">\n        <p class=\"footer-fw__heading\">Quick Links</p>\n        <div class=\"footer-fw__link-grid\">\n          <a href=\"/\">Home</a>\n          <a href=\"/about\">About</a>\n          <a href=\"/menu\">Menu</a>\n          <a href=\"/testimonials\">Reviews</a>\n          <a href=\"/catering\">Catering</a>\n          <a href=\"/gallery\">Gallery</a>\n          <a href=\"/contact\">Contact</a>\n        </div>\n      </div>\n    \n    <div class=\"footer-fw__visit\">\n      <p class=\"footer-fw__heading\">Visit Us</p>\n      <a class=\"footer-fw__line\" href=\"https://www.google.com/maps/search/?api=1&query=1131+E.+Republic+Rd+Springfield+MO+65807\" target=\"_blank\" rel=\"noopener\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5a2.5 2.5 0 110-5 2.5 2.5 0 010 5z\"/></svg><span>1131 E. Republic Rd<br>Springfield, MO 65807</span></a>\n      <a class=\"footer-fw__line\" href=\"tel:4178864224\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M6.62 10.79a15.05 15.05 0 006.59 6.59l2.2-2.2a1 1 0 011.01-.24c1.12.37 2.33.57 3.58.57a1 1 0 011 1V20a1 1 0 01-1 1C10.85 21 3 13.15 3 3a1 1 0 011-1h3.5a1 1 0 011 1c0 1.25.2 2.46.57 3.58a1 1 0 01-.25 1.02l-2.2 2.19z\"/></svg><span>417-886-4224</span></a>\n      <a class=\"footer-fw__line\" href=\"mailto:scrambco@aol.com\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"currentColor\" aria-hidden=\"true\"><path d=\"M20 4H4a2 2 0 00-2 2v12a2 2 0 002 2h16a2 2 0 002-2V6a2 2 0 00-2-2zm0 4l-8 5L4 8V6l8 5 8-5v2z\"/></svg><span>scrambco@aol.com</span></a>\n    </div>\n  </div>\n    <div class=\"footer-bar\">\n      <div>\n        <span>© 2026 Scrambler's Diner. All rights reserved.</span>\n        <span>|</span>\n        <a href=\"/sitemap\">Sitemap</a>\n        <span>|</span>\n        <a href=\"/privacy-policy\">Privacy Policy</a>\n        <span>|</span>\n        <a href=\"/ai-policy\">AI Policy</a>\n        <span>|</span>\n        <a href=\"/ai-readiness\">AI Readiness Service Index</a>\n      </div>\n    </div>\n  </footer>\n</div>";

const SCRIPTS = [
"(function () {\n  /* Robust header scroll sync — prevents hung state after idle/tab sleep */\n  function findHeader() {\n    var el = document.getElementById('site-header');\n    if (el) return el;\n    return document.querySelector('.site-header');\n  }\n  function windowY() {\n    return window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;\n  }\n  function sync() {\n    var header = findHeader();\n    if (!header) return;\n    var y = windowY();\n    var scrolled = y > 24;\n    header.classList.toggle('is-scrolled', scrolled);\n    // Clear any mid-transition hang after tab sleep\n    if (!scrolled) {\n      header.style.removeProperty('transform');\n    }\n  }\n  function onWake() {\n    requestAnimationFrame(function () {\n      sync();\n      requestAnimationFrame(sync);\n    });\n  }\n  window.addEventListener('scroll', sync, { passive: true });\n  window.addEventListener('resize', sync);\n  window.addEventListener('pageshow', onWake);\n  window.addEventListener('focus', onWake);\n  document.addEventListener('visibilitychange', function () {\n    if (!document.hidden) onWake();\n  });\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', sync);\n  } else {\n    sync();\n  }\n  window.addEventListener('load', sync);\n  setTimeout(sync, 50);\n  setTimeout(sync, 300);\n})();",
"(function () {\n  function findEl(id) {\n    var el = document.getElementById(id);\n    if (el) return el;\n    var hosts = document.getElementsByTagName('x-dc');\n    for (var i = 0; i < hosts.length; i++) {\n      var root = hosts[i].shadowRoot || hosts[i];\n      if (root && root.getElementById) {\n        el = root.getElementById(id);\n        if (el) return el;\n      }\n      if (root && root.querySelector) {\n        el = root.querySelector('#' + id);\n        if (el) return el;\n      }\n    }\n    return document.querySelector('#' + id);\n  }\n\n  function scrollY() {\n    var y = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;\n    var nodes = [document.scrollingElement, document.documentElement, document.body];\n    var hosts = document.getElementsByTagName('x-dc');\n    for (var i = 0; i < hosts.length; i++) {\n      nodes.push(hosts[i]);\n      if (hosts[i].shadowRoot) nodes.push(hosts[i].shadowRoot);\n      var p = hosts[i].parentElement;\n      while (p) { nodes.push(p); p = p.parentElement; }\n    }\n    for (var n = 0; n < nodes.length; n++) {\n      var el = nodes[n];\n      if (!el) continue;\n      if (el.scrollTop && el.scrollTop > y) y = el.scrollTop;\n      if (el.querySelectorAll) {\n        var scrollers = el.querySelectorAll('*');\n        for (var s = 0; s < scrollers.length && s < 80; s++) {\n          var c = scrollers[s];\n          if (c.scrollTop > y && c.scrollHeight > c.clientHeight + 40) y = c.scrollTop;\n        }\n      }\n    }\n    return y;\n  }\n\n  function go(root, index) {\n    if (!root) return;\n    var vp = root.querySelector('.sd-carousel__viewport');\n    var track = root.querySelector('.sd-carousel__track');\n    if (!vp || !track) return;\n    var slides = track.children;\n    if (!slides.length) return;\n    var w = vp.clientWidth || vp.offsetWidth;\n    if (!w) return;\n    var i = ((index % slides.length) + slides.length) % slides.length;\n    track.setAttribute('data-i', String(i));\n    var n = 0;\n    while (slides[n]) {\n      slides[n].style.flex = '0 0 ' + w + 'px';\n      slides[n].style.width = w + 'px';\n      slides[n].style.minWidth = w + 'px';\n      n += 1;\n    }\n    track.style.display = 'flex';\n    track.style.transition = 'transform 0.45s ease';\n    track.style.transform = 'translate3d(' + (-i * w) + 'px,0,0)';\n    var dots = root.querySelectorAll('.sd-carousel__dot');\n    for (var d = 0; d < dots.length; d++) {\n      if (d === i) dots[d].classList.add('is-active');\n      else dots[d].classList.remove('is-active');\n    }\n  }\n\n  function step(root, dir) {\n    var track = root.querySelector('.sd-carousel__track');\n    if (!track) return;\n    var i = parseInt(track.getAttribute('data-i') || '0', 10);\n    go(root, i + dir);\n  }\n\n  function onClick(e) {\n    var path = e.composedPath ? e.composedPath() : [];\n    if (!path.length) {\n      var n = e.target;\n      while (n) { path.push(n); n = n.parentNode || n.host; }\n    }\n    for (var i = 0; i < path.length; i++) {\n      var el = path[i];\n      if (!el || !el.getAttribute) continue;\n      var root = el.closest ? el.closest('.sd-carousel') : null;\n      if (!root) continue;\n      if (el.getAttribute('data-sd-dir')) {\n        e.preventDefault();\n        step(root, parseInt(el.getAttribute('data-sd-dir'), 10) || 1);\n        return;\n      }\n      if (el.getAttribute('data-sd-go') != null && el.getAttribute('data-sd-go') !== '') {\n        e.preventDefault();\n        go(root, parseInt(el.getAttribute('data-sd-go'), 10) || 0);\n        return;\n      }\n    }\n  }\n\n  var headerState = false;\n  function syncHeader() {\n    var header = findEl('site-header');\n    if (!header) return;\n    var y = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;\n    var scrolled = y > 24;\n    headerState = scrolled;\n    header.classList.toggle('is-scrolled', scrolled);\n  }\n\n  function initCarousels() {\n    ['griddle-carousel', 'testimonials-carousel'].forEach(function (id) {\n      var root = findEl(id);\n      if (!root) return;\n      var tr0 = root.querySelector('.sd-carousel__track');\n      go(root, parseInt((tr0 && tr0.getAttribute('data-i')) || '0', 10) || 0);\n      if (root.getAttribute('data-auto') === '1') return;\n      root.setAttribute('data-auto', '1');\n      setInterval(function () { step(root, 1); }, 5000);\n    });\n  }\n\n  document.addEventListener('click', onClick, true);\n  // capture scroll from nested preview panes\n  window.addEventListener('scroll', syncHeader, true);\n  document.addEventListener('scroll', syncHeader, true);\n  setInterval(syncHeader, 250);\n\n  function boot() {\n    syncHeader();\n    initCarousels();\n  }\n  boot();\n  setTimeout(boot, 200);\n  setTimeout(boot, 800);\n  setTimeout(boot, 1600);\n  document.addEventListener('DOMContentLoaded', boot);\n  window.addEventListener('load', boot);\n})();"];

export default function Page() {
  useEffect(() => {
    for (const code of SCRIPTS) {
      try {
        // eslint-disable-next-line no-new-func
        new Function(code)();
      } catch (e) {
        console.error(e);
      }
    }
  }, []);

  return <div className="home-page" dangerouslySetInnerHTML={{ __html: HTML }} />;
}
